import React from 'react';
import { PanelMenu } from 'primereact/panelmenu';
import { useNavigate } from 'react-router-dom';

export default function Router() {
    const navigate = useNavigate();
    const items = [
        {
            label: 'Router',
            icon: 'pi pi-palette',
            items: [
                {
                    label: 'Styled',
                    icon: 'pi pi-eraser',
                    command: () => {
                        navigate('/theming');
                    }
                },
                {
                    label: 'Unstyled',
                    icon: 'pi pi-heart',
                    command: () => {
                        navigate('/unstyled');
                    }
                }
            ]
        },
        {
            label: 'Programmatic',
            icon: 'pi pi-link',
            command: () => {
                navigate('/installation');
            }
        },
        {
            label: 'External',
            icon: 'pi pi-home',
            items: [
                {
                    label: 'React.js',
                    icon: 'pi pi-star',
                    command: () => {
                        window.location.href = 'https://react.dev/';
                    }
                },
                {
                    label: 'Vite.js',
                    icon: 'pi pi-bookmark',
                    command: () => {
                        window.location.href = 'https://vite.dev/';
                    }
                }
            ]
        }
    ];

    return (
        <PanelMenu model={items} className="w250" />
    )
}